{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "math",
      "alternatives": [
        "np.isclose(df['tcprtt'], df['synack'] + df['ackdat'], rtol=1e-5, atol=1e-8)"
      ],
      "features": ["tcprtt", "synack", "ackdat"],
      "rationale": "Definition states tcprtt is the sum of synack and ackdat."
    },
    {
      "id": "R2",
      "category": "math",
      "alternatives": [
        "np.where(df['dur'] > 0, np.isclose(df['sload'], df['sbytes'] * 8 / df['dur'], rtol=1e-5, atol=1e-8), True)",
        "np.where(df['dur'] > 0, np.isclose(df['sload'], df['sbytes'] * 8000 / df['dur'], rtol=1e-5, atol=1e-8), True)"
      ],
      "features": ["sload", "sbytes", "dur"],
      "rationale": "sload is source bits per second, so bits = bytes*8, rate = bits/dur; dur may be in seconds or milliseconds."
    },
    {
      "id": "R3",
      "category": "math",
      "alternatives": [
        "np.where(df['dur'] > 0, np.isclose(df['dload'], df['dbytes'] * 8 / df['dur'], rtol=1e-5, atol=1e-8), True)",
        "np.where(df['dur'] > 0, np.isclose(df['dload'], df['dbytes'] * 8000 / df['dur'], rtol=1e-5, atol=1e-8), True)"
      ],
      "features": ["dload", "dbytes", "dur"],
      "rationale": "dload is destination bits per second, so bits = bytes*8, rate = bits/dur; dur may be in seconds or milliseconds."
    },
    {
      "id": "R4",
      "category": "math",
      "alternatives": [
        "np.where(df['spkts'] > 0, np.isclose(df['smean'], df['sbytes'] / df['spkts'], rtol=1e-5, atol=0.5), True)",
        "np.where(df['spkts'] > 0, df['smean'] == np.round(df['sbytes'] / df['spkts']), True)"
      ],
      "features": ["smean", "sbytes", "spkts"],
      "rationale": "smean is mean packet size, so total bytes divided by packet count; may be rounded to integer."
    },
    {
      "id": "R5",
      "category": "math",
      "alternatives": [
        "np.where(df['dpkts'] > 0, np.isclose(df['dmean'], df['dbytes'] / df['dpkts'], rtol=1e-5, atol=0.5), True)",
        "np.where(df['dpkts'] > 0, df['dmean'] == np.round(df['dbytes'] / df['dpkts']), True)"
      ],
      "features": ["dmean", "dbytes", "dpkts"],
      "rationale": "dmean is mean packet size, so total bytes divided by packet count; may be rounded to integer."
    },
    {
      "id": "R6",
      "category": "math",
      "alternatives": [
        "np.where(df['spkts'] > 1, np.isclose(df['sinpkt'], df['dur'] * 1000 / (df['spkts'] - 1), rtol=1e-5, atol=1e-8), True)",
        "np.where(df['spkts'] > 1, np.isclose(df['sinpkt'], df['dur'] / (df['spkts'] - 1), rtol=1e-5, atol=1e-8), True)"
      ],
      "features": ["sinpkt", "dur", "spkts"],
      "rationale": "sinpkt is average interpacket arrival time, so total time divided by number of gaps (spkts-1); dur may be in seconds or milliseconds."
    },
    {
      "id": "R7",
      "category": "math",
      "alternatives": [
        "np.where(df['dpkts'] > 1, np.isclose(df['dinpkt'], df['dur'] * 1000 / (df['dpkts'] - 1), rtol=1e-5, atol=1e-8), True)",
        "np.where(df['dpkts'] > 1, np.isclose(df['dinpkt'], df['dur'] / (df['dpkts'] - 1), rtol=1e-5, atol=1e-8), True)"
      ],
      "features": ["dinpkt", "dur", "dpkts"],
      "rationale": "dinpkt is average interpacket arrival time, so total time divided by number of gaps (dpkts-1); dur may be in seconds or milliseconds."
    },
    {
      "id": "R8",
      "category": "math",
      "alternatives": [
        "np.where(df['dur'] > 0, np.isclose(df['rate'], (df['spkts'] + df['dpkts']) / df['dur'], rtol=1e-5, atol=1e-8), True)",
        "np.where(df['dur'] > 0, np.isclose(df['rate'], df['spkts'] / df['dur'], rtol=1e-5, atol=1e-8), True)",
        "np.where(df['dur'] > 0, np.isclose(df['rate'], (df['sbytes'] + df['dbytes']) / df['dur'], rtol=1e-5, atol=1e-8), True)",
        "np.where(df['dur'] > 0, np.isclose(df['rate'], df['sbytes'] / df['dur'], rtol=1e-5, atol=1e-8), True)"
      ],
      "features": ["rate", "spkts", "dpkts", "dur", "sbytes", "dbytes"],
      "rationale": "rate is undocumented; could be packets per second, source packets per second, bytes per second, or source bytes per second."
    }
  ]
}
